DO $exit_pre$ BEGIN
  IF to_regprocedure('public.fn_exit_sequence_enrollment(integer,uuid,text)') IS NOT NULL AND
     (SELECT md5(prosrc) FROM pg_proc WHERE oid=to_regprocedure('public.fn_exit_sequence_enrollment(integer,uuid,text)'))<>'c74c86363c61614c7d73fa22ec3fc97e' THEN
    RAISE EXCEPTION 'rpc_exit_secuencias_cambio' USING ERRCODE='P0001';
  END IF;
END $exit_pre$;
DROP FUNCTION IF EXISTS public.fn_exit_sequence_enrollment(integer,uuid,text);
-- Secuencias: autorización canónica y referencias estables; motor nativo intacto.
-- No modifica filas. La reversión restaura los cuerpos anteriores y reabre su bypass.
SET LOCAL lock_timeout='1s';
SET LOCAL statement_timeout='4s';
DO $secuencias_delta$
DECLARE
  v_item jsonb;
  v_oid oid;
  v_before text;
  v_meta jsonb;
BEGIN
  IF md5((SELECT prosrc FROM pg_proc WHERE oid='public.fn_crm_exigir_permiso(integer,text[])'::regprocedure))<>'ec142e74a30d5f25d596bd63af911be7'
     OR md5((SELECT prosrc FROM pg_proc WHERE oid='public.app_branch_access(integer)'::regprocedure))<>'d776800d2837a517354ec9b1f7fb9bdc' THEN
    RAISE EXCEPTION 'helper_secuencias_cambio' USING ERRCODE='P0001';
  END IF;
  FOR v_item IN SELECT value FROM jsonb_array_elements($definitions$[{"signature":"fn_enroll_in_sequence(integer,uuid,uuid,uuid,text,uuid,timestamp with time zone)","before":"08144f2f020143d8185ecdc6103a29da","after":"1969a16b09c89b821cefa31d6f8afb31","metadata":{"oid":"3003752","proacl":["postgres=X/postgres","authenticated=X/postgres","service_role=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"13564","proname":"fn_enroll_in_sequence","prorows":0,"pronargs":7,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_org","p_sequence_id","p_opportunity_id","p_customer_id","p_source","p_enrolled_by","p_start_at"],"proargtypes":["23","2950","2950","2950","25","2950","1184"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"pronargdefaults":5},"arguments":"p_org integer, p_sequence_id uuid, p_opportunity_id uuid DEFAULT NULL::uuid, p_customer_id uuid DEFAULT NULL::uuid, p_source text DEFAULT 'manual'::text, p_enrolled_by uuid DEFAULT NULL::uuid, p_start_at timestamp with time zone DEFAULT now()","defaults_normalized":"({CONST :consttype 2950 :consttypmod -1 :constcollid 0 :constlen 16 :constbyval false :constisnull true :location <offset> :constvalue <>} {CONST :consttype 2950 :consttypmod -1 :constcollid 0 :constlen 16 :constbyval false :constisnull true :location <offset> :constvalue <>} {CONST :consttype 25 :consttypmod -1 :constcollid 100 :constlen -1 :constbyval false :constisnull false :location <offset> :constvalue 10 [ 40 0 0 0 109 97 110 117 97 108 ]} {CONST :consttype 2950 :consttypmod -1 :constcollid 0 :constlen 16 :constbyval false :constisnull true :location <offset> :constvalue <>} {FUNCEXPR :funcid 1299 :funcresulttype 1184 :funcretset false :funcvariadic false :funcformat 0 :funccollid 0 :inputcollid 0 :args <> :location <offset>})","definition":"CREATE OR REPLACE FUNCTION public.fn_enroll_in_sequence(p_org integer, p_sequence_id uuid, p_opportunity_id uuid DEFAULT NULL::uuid, p_customer_id uuid DEFAULT NULL::uuid, p_source text DEFAULT 'manual'::text, p_enrolled_by uuid DEFAULT NULL::uuid, p_start_at timestamp with time zone DEFAULT now())\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  v_seq         record;\n  v_customer    uuid := p_customer_id;\n  v_existing    uuid;\n  v_enrollment  uuid;\n  v_steps       integer := 0;\n  v_first       timestamptz;\n  v_first_step  uuid;\n  v_first_run   uuid;\n  r             record;\n  v_run_id      uuid;\n  v_job_id      uuid;\n  v_sched       timestamptz;\nBEGIN\n  IF p_org IS NULL OR p_sequence_id IS NULL THEN\n    RAISE EXCEPTION 'invalid_arguments' USING ERRCODE = 'P0001';\n  END IF;\n  IF p_opportunity_id IS NULL AND p_customer_id IS NULL THEN\n    RAISE EXCEPTION 'opportunity_or_customer_required' USING ERRCODE = 'P0001';\n  END IF;\n\n  -- Con sesión de usuario (auth.uid()) exigimos membresía activa: la función es\n  -- SECURITY DEFINER y salta RLS. Con service_role auth.uid() es NULL.\n  IF auth.uid() IS NOT NULL AND NOT EXISTS (\n    SELECT 1 FROM organization_members om\n     WHERE om.user_id = auth.uid() AND om.organization_id = p_org AND om.is_active = true\n  ) THEN\n    RAISE EXCEPTION 'forbidden_org' USING ERRCODE = 'P0001';\n  END IF;\n\n  SELECT id, is_active INTO v_seq FROM sequences\n   WHERE id = p_sequence_id AND organization_id = p_org;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'sequence_not_found' USING ERRCODE = 'P0001';\n  END IF;\n  IF NOT v_seq.is_active THEN\n    RAISE EXCEPTION 'sequence_inactive' USING ERRCODE = 'P0001';\n  END IF;\n\n  IF p_opportunity_id IS NOT NULL THEN\n    SELECT customer_id INTO v_customer FROM opportunities\n     WHERE id = p_opportunity_id AND organization_id = p_org;\n    IF NOT FOUND THEN\n      RAISE EXCEPTION 'opportunity_not_found' USING ERRCODE = 'P0001';\n    END IF;\n    v_customer := COALESCE(v_customer, p_customer_id);\n  ELSE\n    PERFORM 1 FROM customers WHERE id = p_customer_id AND organization_id = p_org;\n    IF NOT FOUND THEN\n      RAISE EXCEPTION 'customer_not_found' USING ERRCODE = 'P0001';\n    END IF;\n  END IF;\n\n  -- Inscripción viva (active|paused) ya existente -> no duplicar.\n  SELECT id INTO v_existing FROM sequence_enrollments\n   WHERE sequence_id = p_sequence_id\n     AND organization_id = p_org\n     AND status IN ('active','paused')\n     AND ((p_opportunity_id IS NOT NULL AND opportunity_id = p_opportunity_id)\n       OR (p_opportunity_id IS NULL AND opportunity_id IS NULL AND customer_id = p_customer_id))\n   LIMIT 1;\n  IF v_existing IS NOT NULL THEN\n    RETURN jsonb_build_object('created', false, 'reason', 'already_active', 'enrollment_id', v_existing, 'steps', 0);\n  END IF;\n\n  IF NOT EXISTS (\n    SELECT 1 FROM sequence_steps\n     WHERE sequence_id = p_sequence_id AND organization_id = p_org AND is_active = true\n  ) THEN\n    RAISE EXCEPTION 'sequence_has_no_active_steps' USING ERRCODE = 'P0001';\n  END IF;\n\n  INSERT INTO sequence_enrollments (organization_id, sequence_id, opportunity_id, customer_id, status, enrolled_at, source, enrolled_by)\n  VALUES (p_org, p_sequence_id, p_opportunity_id, v_customer, 'active', COALESCE(p_start_at, now()), COALESCE(p_source,'manual'), p_enrolled_by)\n  RETURNING id INTO v_enrollment;\n\n  FOR r IN\n    SELECT id, step_number, delay_days, delay_hours\n      FROM sequence_steps\n     WHERE sequence_id = p_sequence_id AND organization_id = p_org AND is_active = true\n     ORDER BY step_number\n  LOOP\n    v_sched := COALESCE(p_start_at, now())\n             + make_interval(days => COALESCE(r.delay_days, 0), hours => COALESCE(r.delay_hours, 0));\n\n    INSERT INTO sequence_step_runs (organization_id, enrollment_id, step_id, status, scheduled_at)\n    VALUES (p_org, v_enrollment, r.id, 'pending', v_sched)\n    RETURNING id INTO v_run_id;\n\n    v_steps := v_steps + 1;\n\n    -- Solo el PRIMER paso (por step_number) se encola aquí: el resto lo encola\n    -- `processStepRun` al terminar el anterior (programación encadenada, N1).\n    IF v_first_run IS NULL THEN\n      v_first_run  := v_run_id;\n      v_first      := v_sched;\n      v_first_step := r.id;\n    END IF;\n  END LOOP;\n\n  v_job_id := fn_enqueue_job(p_org, 'sequence_step',\n                             jsonb_build_object('step_run_id', v_first_run, 'enrollment_id', v_enrollment),\n                             v_first, 'seqrun:' || v_first_run::text, 3);\n  UPDATE sequence_step_runs SET job_id = v_job_id WHERE id = v_first_run;\n\n  -- Barrido de respaldo por organización (N2): singleton por dedupe_key.\n  PERFORM fn_enqueue_job(p_org, 'time_events',\n                         jsonb_build_object('scope', 'sequences'),\n                         now() + interval '15 minutes',\n                         'time_events:' || p_org::text, 3);\n\n  UPDATE sequence_enrollments\n     SET next_run_at = v_first, current_step_id = v_first_step\n   WHERE id = v_enrollment;\n\n  RETURN jsonb_build_object('created', true, 'enrollment_id', v_enrollment, 'steps', v_steps, 'first_run_at', v_first);\nEND $function$\n"},{"signature":"fn_resume_sequence_enrollment(integer,uuid)","before":"4a215017a83271e5d49a0fdeb138b305","after":"2657c98e120c0394abd5bee5be237e95","metadata":{"oid":"3003877","proacl":["postgres=X/postgres","authenticated=X/postgres","service_role=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"13564","proname":"fn_resume_sequence_enrollment","prorows":0,"pronargs":2,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_org","p_enrollment_id"],"proargtypes":["23","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"pronargdefaults":0},"arguments":"p_org integer, p_enrollment_id uuid","defaults_normalized":null,"definition":"CREATE OR REPLACE FUNCTION public.fn_resume_sequence_enrollment(p_org integer, p_enrollment_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  v_enroll   record;\n  v_next     record;\n  v_sched    timestamptz;\n  v_job_id   uuid;\nBEGIN\n  IF p_org IS NULL OR p_enrollment_id IS NULL THEN\n    RAISE EXCEPTION 'invalid_arguments' USING ERRCODE = 'P0001';\n  END IF;\n\n  IF auth.uid() IS NOT NULL AND NOT EXISTS (\n    SELECT 1 FROM organization_members om\n     WHERE om.user_id = auth.uid() AND om.organization_id = p_org AND om.is_active = true\n  ) THEN\n    RAISE EXCEPTION 'forbidden_org' USING ERRCODE = 'P0001';\n  END IF;\n\n  SELECT id, status INTO v_enroll FROM sequence_enrollments\n   WHERE id = p_enrollment_id AND organization_id = p_org;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'enrollment_not_found' USING ERRCODE = 'P0001';\n  END IF;\n  IF v_enroll.status <> 'paused' THEN\n    RETURN jsonb_build_object('resumed', false, 'reason', 'not_paused', 'status', v_enroll.status);\n  END IF;\n\n  SELECT sr.id, sr.scheduled_at, s.id AS step_id\n    INTO v_next\n    FROM sequence_step_runs sr\n    JOIN sequence_steps s ON s.id = sr.step_id\n   WHERE sr.enrollment_id = p_enrollment_id\n     AND sr.organization_id = p_org\n     AND sr.status = 'pending'\n   ORDER BY s.step_number\n   LIMIT 1;\n\n  IF NOT FOUND THEN\n    UPDATE sequence_enrollments\n       SET status = 'completed', paused_reason = NULL, paused_at = NULL,\n           exited_at = now(), exit_reason = 'all_steps_completed'\n     WHERE id = p_enrollment_id AND organization_id = p_org;\n    RETURN jsonb_build_object('resumed', false, 'reason', 'no_pending_steps', 'status', 'completed');\n  END IF;\n\n  -- Un paso cuya hora ya pasó se reprograma a ahora (no se dispara \"en el pasado\").\n  v_sched := GREATEST(v_next.scheduled_at, now());\n  UPDATE sequence_step_runs SET scheduled_at = v_sched\n   WHERE id = v_next.id AND organization_id = p_org;\n\n  UPDATE sequence_enrollments\n     SET status = 'active', paused_reason = NULL, paused_at = NULL,\n         next_run_at = v_sched, current_step_id = v_next.step_id\n   WHERE id = p_enrollment_id AND organization_id = p_org;\n\n  v_job_id := fn_enqueue_job(p_org, 'sequence_step',\n                             jsonb_build_object('step_run_id', v_next.id, 'enrollment_id', p_enrollment_id),\n                             v_sched, 'seqrun:' || v_next.id::text, 3);\n  UPDATE sequence_step_runs SET job_id = v_job_id WHERE id = v_next.id AND organization_id = p_org;\n\n  PERFORM fn_enqueue_job(p_org, 'time_events',\n                         jsonb_build_object('scope', 'sequences'),\n                         now() + interval '15 minutes',\n                         'time_events:' || p_org::text, 3);\n\n  RETURN jsonb_build_object('resumed', true, 'enrollment_id', p_enrollment_id,\n                            'step_run_id', v_next.id, 'next_run_at', v_sched, 'status', 'active');\nEND $function$\n"}]$definitions$::jsonb) LOOP
    v_oid:=to_regprocedure(v_item->>'signature');
    IF v_oid IS NULL THEN RAISE EXCEPTION 'rpc_secuencias_ausente' USING ERRCODE='P0001'; END IF;
    SELECT md5(p.prosrc),to_jsonb(p)-'prosrc'-'proargdefaults' INTO v_before,v_meta FROM pg_proc p WHERE p.oid=v_oid;
    IF v_before NOT IN (v_item->>'before',v_item->>'after') OR v_meta IS DISTINCT FROM v_item->'metadata'
       OR pg_get_function_arguments(v_oid) IS DISTINCT FROM v_item->>'arguments'
       OR (SELECT regexp_replace(p.proargdefaults::text,':location -?[0-9]+',':location <offset>','g') FROM pg_proc p WHERE p.oid=v_oid)
            IS DISTINCT FROM v_item->>'defaults_normalized' THEN
      RAISE EXCEPTION 'contrato_secuencias_cambio' USING ERRCODE='P0001';
    END IF;
    IF v_before<>v_item->>'after' THEN EXECUTE v_item->>'definition'; END IF;
    IF (SELECT md5(p.prosrc) FROM pg_proc p WHERE p.oid=v_oid)<>v_item->>'after'
       OR (SELECT to_jsonb(p)-'prosrc'-'proargdefaults' FROM pg_proc p WHERE p.oid=v_oid) IS DISTINCT FROM v_meta
       OR pg_get_function_arguments(v_oid) IS DISTINCT FROM v_item->>'arguments'
       OR (SELECT regexp_replace(p.proargdefaults::text,':location -?[0-9]+',':location <offset>','g') FROM pg_proc p WHERE p.oid=v_oid)
            IS DISTINCT FROM v_item->>'defaults_normalized' THEN
      RAISE EXCEPTION 'contrato_secuencias_no_conservado' USING ERRCODE='P0001';
    END IF;
  END LOOP;
END $secuencias_delta$;
